WITH kept_keys AS (SELECT device_code FROM device_readings INTERSECT ALL SELECT device_code FROM device_readings WHERE HOUR(reading_ts) BETWEEN 10 AND 18), reconciled AS (SELECT s.* FROM device_readings s INNER JOIN kept_keys k ON s.device_code = k.device_code) SELECT CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, CORR(temp_c, humidity) AS corr_temp_c_humidity, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT(DISTINCT id) AS distinct_ids FROM reconciled GROUP BY CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END HAVING cnt >= 1 ORDER BY status_bits_tier DESC;
